<?php declare(strict_types=1);require __DIR__.'/app/bootstrap.php';$user=require_login();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$full=trim($_POST['full_name']??'');$phone=trim($_POST['phone']??'');$position=trim($_POST['position']??'');if($full&&$phone){db()->prepare('UPDATE users SET full_name=?,phone=?,position=? WHERE id=?')->execute([$full,$phone,$position?:null,$user['id']]);flash('success','Profile updated.');redirect('profile');}flash('error','Name and phone number are required.');}$pageTitle='Your profile';require __DIR__.'/includes/auth-header.php';?>
<section class="auth-card compact"><p class="kicker">PERSONAL PROFILE</p><h1>Your details.</h1><p>Your role and location access are managed separately.</p><form method="post" class="stack"><?=csrf_field()?><label>Full name<input name="full_name" value="<?=e($user['full_name'])?>" required></label><label>Email address<input value="<?=e($user['email'])?>" disabled><small>Email cannot be changed here.</small></label><label>Phone number<input name="phone" value="<?=e($user['phone'])?>" required></label><label>Position / title<input name="position" value="<?=e($user['position'])?>"></label><button class="primary">Save profile</button></form><a class="back-link" href="dashboard">← Back to dashboard</a></section><?php require __DIR__.'/includes/auth-footer.php';?>
